# П8 ПРОШЁЛ ТРИ СОСТОЯНИЯ, и это стоит держать в одном месте.
# (1) БЫЛ порчей (ждали 3): «Знак в знак» несёт «требует «невозможное» а
#     меньше б» и «требует «обратно» б не больше а» — сам автор пробы назвал
#     посылку «невозможное». Приём Ч365 на цель «1 равен 2» честно не брался:
#     она не переписывается ни одним законом из закрытого списка.
# (2) СТАЛ кодом 0 (задача 3314): «разбор цели по условию» научился отдельному
#     доводу — если требуемые допущения ПОПАРНО НЕСОВМЕСТИМЫ (а тут ровно так:
#     из «а меньше б» и «б не больше а» следует «а меньше а»), постусловие
#     истинно ПУСТО, каким бы оно ни было. «Знак в знак» закрылся законно.
# (3) СНОВА 3 (задача 3781), и вот почему. Код 0 требует, чтобы записи хватило
#     на ВСЕ четыре утверждения, а не на одно. Три остальных — «сумма
#     наоборот» (`результат равен (б плюс а)` при теле `а плюс б`), «длина
#     растёт на один», «сумма трёх» — это ∀-цели, и закрывал их КАЛЬКУЛЯТОР:
#     переписывание тела законами. Калькулятор снят, и запись честно говорит
#     «НЕ ПРОВЕРЕНО»: «Знак в знак» по-прежнему закрыт несовместимыми
#     допущениями (это проверено диагностическим прогоном), а за три ∀-цели
#     чекер больше не ручается. Класс остался C: честную запись нельзя
#     ОТВЕРГНУТЬ (код 1), а код 3 отвержением не является.
mut identity-after-rewrite p8-the-same-lie-under-an-assumption 3 C
mut identity-after-rewrite p9-index-outside-the-list-bounds    3 P
mut identity-after-rewrite p10-e2-yields-a-foreign-element     3 P

say ""
say "── Ч375: термин РЯДОМ с номером сверяется с исходником, а не заменяет его (9612) ──"
# Исходники — настоящие, из дерева: только записи ниже подложные. Термин
# ставится РЯДОМ с существующим «строка N» (Ч19-приёмом sed по неизменной
# строке), поэтому проба честно показывает НОВОЕ поведение третьей ветки, а не
# выдуманный формат. Имена латиницей: см. шапку файла.
D375=$ZAP/term-beside-line-number
FAKT=flang/proof/examples/corpus-factorial.flang
# Ч7104: у четырёх ЧЕСТНЫХ проб ниже ожидание 3 → 0. Пробы стерегут третью
# ветку Ч375 и о долге ничего не говорят; тройку они ждали лишь потому, что
# спуск `corpus-factorial` тогда не проигрывался. Приёмом 7107 (произведение
# строго положительного довода индукции на допущение) он проигрывается, и
# запись честно стала Р0. Оставить тут 3 значило бы зашить вчерашний долг в
# ожидаемый ответ — тот самый сторож, что стережёт снимок, а не свойство.
grep -q 'ни произведение строго положительного' "$CHEK/checker.c" || {
  say "ПРОВАЛ Ч375: ожидания правлены под приём 7107, а приёма в сверщике нет"; BAD=$((BAD+1)); }
opyt C "Ч375 00 нетронутый: запись как была"                          0 "$FAKT" "$D375/00-untouched.record"
opyt C "Ч375 01 термин и номер согласны — остаётся зелёным, как было" 0 "$FAKT" "$D375/01-term-and-line-agree.record"
opyt P "Ч375 02 термин цели против строки под номером"                1 "$FAKT" "$D375/02-goal-term-against-the-line.record"
opyt P "Ч375 03 термин шага против строки под номером"                1 "$FAKT" "$D375/03-step-term-against-the-line.record"
opyt C "Ч375 04 термин цели без номера, согласен с обещанным"         0 "$FAKT" "$D375/04-goal-term-without-line-agrees.record"
opyt P "Ч375 05 термин цели без номера — против обещанного"           1 "$FAKT" "$D375/05-goal-term-without-line-against-the-promise.record"
opyt C "Ч375 06 термин шага без номера, согласен с обоснованием"      0 "$FAKT" "$D375/06-step-term-without-line-agrees.record"
opyt P "Ч375 07 термин шага без номера — против обоснования"          1 "$FAKT" "$D375/07-step-term-without-line-against-the-justification.record"
opyt C "Ч375 08 термин «по примеру» несёт своё имя в ёлочках"         0 "$TL" "$D375/08-term-by-example-with-a-name-inside.record"
opyt P "Ч375 09 термин с ЛОЖНЫМ именем внутри — расхождение поймано"  1 "$TL" "$D375/09-term-with-a-false-name-inside.record"

